#nullable enable // autogenerated

using MVZ2Logic.Curses;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Modifiers;

namespace MVZ2.GameContent.Buffs.Level
{
    public abstract class CurseBuffDefinition : BuffDefinition, ICurseBuffDefinition
    {
        public CurseBuffDefinition(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new IntModifier(LogicLevelProps.CURSE_COUNT, IntegerOperator.Add, 1));
        }
    }
}
